function mountLearningScene(canvas, preferences, signal) {
  if (!canvas) return () => {};
  const context = canvas.getContext('2d');
  if (!context) return () => {};
  const width = 680;
  const height = 590;
  const center = { x: 343, y: 302 };
  const tau = Math.PI * 2;
  const spheres = [
    { x: 148, y: 155, type: 'code', color: '#bbd599', title: 'Programación' },
    { x: 515, y: 115, type: 'atom', color: '#f1cb84', title: 'Ciencia' },
    { x: 540, y: 442, type: 'graph', color: '#bfdbad', title: 'Matemáticas' },
    { x: 136, y: 458, type: 'pencil', color: '#e7bd74', title: 'Lectura y escritura' }
  ];
  const orbits = [
    { a: 273, b: 103, tilt: -.31 },
    { a: 240, b: 148, tilt: .45 },
    { a: 176, b: 227, tilt: -.52 }
  ];
  const particles = Array.from({ length: 236 }, (_, index) => {
    const orbit = orbits[index % orbits.length];
    return {
      orbit,
      angle: index * 2.39996,
      speed: (.16 + (index % 9) * .028) * (index % 4 === 0 ? -1 : 1),
      drift: (index % 19) - 9,
      size: index % 11 === 0 ? 2.3 : index % 3 === 0 ? 1.55 : .85,
      warm: index % 5 < 2
    };
  });
  let frame = 0;
  let visible = false;
  let pointer = null;
  let scale = 1;
  let offsetX = 0;
  let offsetY = 0;
  let pixelRatio = 1;
  let elapsed = 0;
  let previous = 0;
  let position = 0;

  function path(callback) {
    context.beginPath();
    callback(context);
  }

  function orbitPoint(orbit, theta, drift = 0) {
    const x = Math.cos(theta) * (orbit.a + drift);
    const y = Math.sin(theta) * (orbit.b + drift);
    return {
      x: center.x + x * Math.cos(orbit.tilt) - y * Math.sin(orbit.tilt),
      y: center.y + x * Math.sin(orbit.tilt) + y * Math.cos(orbit.tilt)
    };
  }

  function drawOrbit(orbit, index) {
    context.lineWidth = 1;
    context.strokeStyle = index === 0 ? '#ecbd695b' : '#c0daa644';
    if (index === 2) context.setLineDash([2, 6]);
    path(p => p.ellipse(center.x, center.y, orbit.a, orbit.b, orbit.tilt, 0, tau));
    context.stroke();
    context.setLineDash([]);
  }

  function pageShape(direction, layer) {
    const x = value => center.x + direction * value;
    path(p => {
      p.moveTo(center.x, 258 + layer);
      p.bezierCurveTo(x(58), 221 + layer, x(104), 217 + layer, x(160), 231 + layer);
      p.lineTo(x(144), 357 + layer);
      p.bezierCurveTo(x(93), 339 + layer, x(50), 351 + layer, center.x, 392 + layer);
      p.closePath();
    });
  }

  function drawBook(time) {
    context.save();
    context.translate(0, Math.sin(time * .9) * 5);
    context.lineJoin = 'round';
    for (const side of [-1, 1]) {
      for (const layer of [14, 7, 0]) {
        pageShape(side, layer);
        if (layer === 0) {
          const paper = context.createLinearGradient(center.x + side * 155, 241, center.x, 387);
          paper.addColorStop(0, side === -1 ? '#476044' : '#5b693f');
          paper.addColorStop(.46, '#304a38');
          paper.addColorStop(1, '#162e26');
          context.fillStyle = paper;
        } else context.fillStyle = layer === 14 ? '#152b24' : '#263c2f';
        context.fill();
        context.strokeStyle = layer ? '#e7bd7188' : '#f8d897';
        context.lineWidth = layer ? 1.25 : 2;
        context.stroke();
      }
      for (let row = 0; row < 7; row++) {
        const y = 264 + row * 12;
        const x = value => center.x + side * value;
        path(p => {
          p.moveTo(x(23), y + 12);
          p.bezierCurveTo(x(68), y - 8, x(96), y - 16, x(row % 3 ? 126 : 108), y - 8);
        });
        context.lineWidth = .9;
        context.strokeStyle = row % 3 === 0 ? '#e7bd7191' : '#d7e3bf60';
        context.stroke();
      }
    }
    context.strokeStyle = '#ffdfa5';
    context.lineWidth = 1.6;
    path(p => { p.moveTo(center.x, 257); p.lineTo(center.x, 396); });
    context.stroke();
    context.restore();
  }

  function drawSymbol(type) {
    if (type === 'code') {
      path(p => {
        p.moveTo(-7, -10); p.lineTo(-19, 0); p.lineTo(-7, 10);
        p.moveTo(7, -10); p.lineTo(19, 0); p.lineTo(7, 10);
        p.moveTo(4, -15); p.lineTo(-4, 15);
      });
      context.stroke();
    } else if (type === 'atom') {
      for (const angle of [0, Math.PI / 3, -Math.PI / 3]) {
        path(p => p.ellipse(0, 0, 19, 7, angle, 0, tau));
        context.stroke();
      }
      path(p => p.arc(0, 0, 2.6, 0, tau));
      context.fill();
    } else if (type === 'graph') {
      path(p => {
        p.moveTo(-17, -15); p.lineTo(-17, 15); p.lineTo(18, 15);
        p.moveTo(-13, 8); p.quadraticCurveTo(-3, -13, 3, -4); p.quadraticCurveTo(12, 8, 17, -14);
      });
      context.stroke();
    } else {
      context.rotate(-Math.PI / 4);
      path(p => { p.rect(-15, -4, 24, 8); p.moveTo(9, -4); p.lineTo(17, 0); p.lineTo(9, 4); });
      context.stroke();
    }
  }

  function drawBadge(badge, index, time) {
    context.save();
    const rise = Math.sin(time * 1.05 + index * 1.75) * 6;
    context.translate(badge.x, badge.y + rise);
    context.fillStyle = '#182f27';
    context.strokeStyle = badge.color + '9e';
    context.lineWidth = 1;
    path(p => p.roundRect(-28, -28, 56, 56, 12));
    context.fill();
    context.stroke();
    context.strokeStyle = badge.color;
    context.fillStyle = badge.color;
    context.lineWidth = 1.7;
    context.save();
    drawSymbol(badge.type);
    context.restore();
    context.font = '650 12px "Acoolsure DM", sans-serif';
    context.textAlign = 'center';
    context.fillText(badge.title, 0, 47);
    context.restore();
  }

  function paint() {
    context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
    context.clearRect(0, 0, canvas.width / pixelRatio, canvas.height / pixelRatio);
    context.translate(offsetX, offsetY);
    context.scale(scale, scale);
    context.translate(0, -position * 14);
    const light = context.createRadialGradient(center.x, center.y, 30, center.x, center.y, 288);
    light.addColorStop(0, '#b1cb7a29');
    light.addColorStop(.53, '#7ba26717');
    light.addColorStop(1, '#7ba26700');
    context.fillStyle = light;
    context.fillRect(20, 15, 640, 555);
    orbits.forEach(drawOrbit);
    for (const item of particles) {
      const point = orbitPoint(item.orbit, item.angle + elapsed * item.speed, item.drift);
      if (pointer) {
        const x = point.x - pointer.x;
        const y = point.y - pointer.y;
        const distance = Math.hypot(x, y);
        if (distance > 0 && distance < 94) {
          const push = (1 - distance / 94) * 46 / distance;
          point.x += x * push;
          point.y += y * push;
        }
      }
      context.globalAlpha = .48 + .4 * Math.sin(item.angle + elapsed * 1.15) ** 2;
      context.fillStyle = item.warm ? '#f8d798' : '#c7e5af';
      path(p => p.arc(point.x, point.y, item.size, 0, tau));
      context.fill();
    }
    context.globalAlpha = 1;
    drawBook(elapsed);
    spheres.forEach((badge, index) => drawBadge(badge, index, elapsed));
  }

  function tick(now) {
    frame = 0;
    if (!visible || preferences.matches || signal.aborted) return;
    if (previous) elapsed += Math.min(.035, (now - previous) / 1000);
    previous = now;
    position = Math.max(0, Math.min(1, -canvas.getBoundingClientRect().top / canvas.clientHeight));
    paint();
    frame = requestAnimationFrame(tick);
  }

  function resize() {
    const bounds = canvas.getBoundingClientRect();
    if (!bounds.width || !bounds.height) return;
    pixelRatio = Math.min(1.75, devicePixelRatio || 1);
    canvas.width = Math.ceil(bounds.width * pixelRatio);
    canvas.height = Math.ceil(bounds.height * pixelRatio);
    const narrow = bounds.width <= 700;
    scale = Math.min(bounds.width / (narrow ? 610 : 980), bounds.height / (narrow ? 870 : height));
    offsetX = narrow ? (bounds.width - width * scale) / 2 : bounds.width - width * scale - bounds.width * .025;
    offsetY = narrow ? bounds.height * .98 - height * scale : (bounds.height - height * scale) / 2;
    paint();
  }

  function setMotion() {
    cancelAnimationFrame(frame);
    frame = 0;
    previous = 0;
    if (visible && !preferences.matches) frame = requestAnimationFrame(tick);
    if (preferences.matches) {
      elapsed = 0;
      pointer = null;
      position = 0;
      paint();
    }
  }

  const sizes = new ResizeObserver(resize);
  sizes.observe(canvas);
  const view = new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting;
    setMotion();
  });
  view.observe(canvas);
  preferences.addEventListener('change', setMotion, { signal });
  const hero = canvas.closest('.hero');
  hero.addEventListener('pointermove', event => {
    if (event.pointerType === 'touch' || preferences.matches) return;
    const box = canvas.getBoundingClientRect();
    pointer = { x: (event.clientX - box.left - offsetX) / scale, y: (event.clientY - box.top - offsetY) / scale };
  }, { passive: true, signal });
  hero.addEventListener('pointerleave', () => { pointer = null; }, { passive: true, signal });
  document.fonts.ready.then(() => { if (!signal.aborted) resize(); });
  resize();

  return () => {
    sizes.disconnect();
    view.disconnect();
    cancelAnimationFrame(frame);
  };
}

function mountParticleTitle(title, preferences, signal) {
  if (!title) return () => {};
  const canvas = title.querySelector('.title-particle-canvas');
  const painter = canvas.getContext('2d');
  const stencil = document.createElement('canvas');
  const mask = stencil.getContext('2d', { willReadFrequently: true });
  if (!painter || !mask) return () => {};

  const letters = [...title.querySelectorAll('.hero-line > *')];
  const colors = ['#fff3d5', '#e6d4ac', '#f3ce8b', '#deaa5c'];
  const layers = colors.map(color => ({ color, dots: [] }));
  let ready = false;
  let visible = false;
  let pointer = null;
  let frame = 0;
  let ratio = 1;

  function paint() {
    frame = 0;
    if (!visible || preferences.matches || !layers.some(layer => layer.dots.length)) return;
    painter.clearRect(0, 0, canvas.width / ratio, canvas.height / ratio);
    painter.globalAlpha = .26;
    painter.drawImage(stencil, 0, 0);
    painter.globalAlpha = 1;
    let moving = false;
    for (const { color, dots } of layers) {
      painter.fillStyle = color;
      for (const dot of dots) {
        let targetX = dot.x;
        let targetY = dot.y;
        if (pointer) {
          const dx = dot.x - pointer.x;
          const dy = dot.y - pointer.y;
          const distance = Math.hypot(dx, dy);
          if (distance > 0 && distance < 64) {
            const push = (1 - distance / 64) * (11 + dot.weight * 18) / distance;
            targetX += dx * push;
            targetY += dy * push;
          }
        }
        const dx = targetX - dot.currentX;
        const dy = targetY - dot.currentY;
        dot.currentX += dx * .16;
        dot.currentY += dy * .16;
        moving ||= Math.abs(dx) + Math.abs(dy) > .18;
        painter.fillRect(dot.currentX, dot.currentY, dot.size, dot.size);
      }
    }
    title.classList.add('particles-visible');
    if (moving) frame = requestAnimationFrame(paint);
  }

  function schedule() {
    if (!frame && visible && !preferences.matches) frame = requestAnimationFrame(paint);
  }

  function rebuild() {
    if (!ready || signal.aborted || preferences.matches) {
      title.classList.remove('particles-visible');
      return;
    }
    const area = canvas.getBoundingClientRect();
    const width = Math.ceil(area.width);
    const height = Math.ceil(area.height);
    if (!width || !height) return;
    title.classList.remove('particles-visible');
    const first = !layers.some(layer => layer.dots.length);
    for (const layer of layers) layer.dots.length = 0;
    ratio = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.ceil(width * ratio);
    canvas.height = Math.ceil(height * ratio);
    stencil.width = width;
    stencil.height = height;
    painter.setTransform(ratio, 0, 0, ratio, 0, 0);
    for (const [index, letter] of letters.entries()) {
      const style = getComputedStyle(letter);
      const rect = letter.getBoundingClientRect();
      const text = index === 0 ? letter.textContent.toLocaleUpperCase('es') : letter.textContent;
      mask.font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
      if ('letterSpacing' in mask) mask.letterSpacing = style.letterSpacing;
      const metrics = mask.measureText(text);
      const baseline = rect.top - area.top + (rect.height + metrics.actualBoundingBoxAscent - metrics.actualBoundingBoxDescent) / 2;
      mask.fillStyle = index === 0 ? '#f2e5c5' : '#e4ad64';
      mask.fillText(text, rect.left - area.left, baseline);
    }
    const pixels = mask.getImageData(0, 0, width, height).data;
    const step = Math.max(2, Math.ceil(Math.sqrt(width * height / 32000)));
    for (let y = 0; y < height; y += step) {
      for (let x = 0; x < width; x += step) {
        const pixel = (y * width + x) * 4;
        if (pixels[pixel + 3] < 155) continue;
        const base = pixels[pixel + 2] > 155 ? 0 : 2;
        const weight = ((x * 13 + y * 7) % 23) / 22;
        const spread = first ? 24 + weight * 26 : 0;
        const angle = (x * 19 + y * 11) * .27;
        layers[base + (weight < .26 ? 1 : 0)].dots.push({
          x, y, weight, size: step * (.68 + weight * .48),
          currentX: x + Math.sin(angle) * spread,
          currentY: y + Math.cos(angle) * spread * .62
        });
      }
    }
    schedule();
  }

  const sizeObserver = new ResizeObserver(rebuild);
  sizeObserver.observe(title);
  const view = new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting;
    if (visible) schedule();
    else pointer = null;
  });
  view.observe(title);
  document.fonts.ready.then(() => {
    ready = true;
    rebuild();
  });
  preferences.addEventListener('change', rebuild, { signal });
  title.addEventListener('pointermove', event => {
    if (event.pointerType === 'touch' || preferences.matches) return;
    const area = canvas.getBoundingClientRect();
    pointer = { x: event.clientX - area.left, y: event.clientY - area.top };
    schedule();
  }, { passive: true, signal });
  title.addEventListener('pointerleave', () => {
    pointer = null;
    schedule();
  }, { passive: true, signal });

  return () => {
    sizeObserver.disconnect();
    view.disconnect();
    cancelAnimationFrame(frame);
    title.classList.remove('particles-visible');
  };
}


